import{_ as t,a as o,b as a}from"./chunks/a017272816a0ef1329d6.BpGUEYVb.js";import{_ as r}from"./chunks/a7b3a30358c086b3a39e.CS8YSe9M.js";import{_ as n,o as i,c as s,a6 as p}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"Working Less Helps You Make More Money (The 4-Hour Workday)","description":"","frontmatter":{"title":"Working Less Helps You Make More Money (The 4-Hour Workday)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/working-less-helps-you-make-more-money-the-4-hour-workday.md","filePath":"en/letters/working-less-helps-you-make-more-money-the-4-hour-workday.md"}'),h={name:"en/letters/working-less-helps-you-make-more-money-the-4-hour-workday.md"};function l(u,e,d,c,m,y){return i(),s("div",null,[...e[0]||(e[0]=[p('<h1 id="working-less-helps-you-make-more-money-the-4-hour-workday" tabindex="-1">Working Less Helps You Make More Money (The 4-Hour Workday) <a class="header-anchor" href="#working-less-helps-you-make-more-money-the-4-hour-workday" aria-label="Permalink to &quot;Working Less Helps You Make More Money (The 4-Hour Workday)&quot;">​</a></h1><p>Dan Koe · 2023-06-10 · <a href="https://thedankoe.com/letters/working-less-helps-you-make-more-money-the-4-hour-workday/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/working-less-helps-you-make-more-money-the-4-hour-workday">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/YW7yTzqedu8?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>People don’t believe me when I tell them I work less than 4 hours a day.</p><p>Especially at this point in my life where I’ve been working 1-2 hours a day max.</p><p>How?</p><p><strong>1) I’ve always focused on eliminating the things I don’t like in my life.</strong></p><p>I didn’t like long client calls or hosting podcasts, so I stopped doing them.</p><p>Those alone gave me back hours each week of my time.</p><p>Of course, I couldn’t do it immediately.</p><p>I had to <em>create a solution to my own problems.</em></p><p>Client work served its purpose until I realized personal branding was a way out. So I made that my priority project each morning for a year.</p><p>(By the way, if you can’t tell, this is mainly for internet entrepreneurs and creatives.)</p><p><strong>2) I’ve always focused on the highest leverage activities possible.</strong></p><p>Freelance and consulting work is a great starting point but demands a lot of time.</p><p>If you want more freedom, you need a product that can sell in your sleep, without personal effort.</p><p>With time I transitioned out of client work and used my results in brand advising to create a digital product stack.</p><p>The time-to-money ratio must decrease as you grow.</p><p>Next, I realized that writing was my ideal traffic generation method.</p><p>I write for 1-2 hours every single morning.</p><p>Yes, even on weekends.</p><p>No, I don’t want to do anything else with that time.</p><p>My writing gets repurposed to every single social media platform so that my audience continues to grow.</p><p>This is where most people fail.</p><p>They take courses, which illustrate exactly what the high-leverage tasks are, but then do the exact opposite.</p><p>When they ask, “Dan, why am I not getting results?”</p><p>I ask what they are doing on a daily, focused basis and it is close to nothing.</p><p>They are not performing the actions that get results on a daily basis.</p><p>They are procrastinating for 3 hours and doing things that don’t matter for another 8.</p><p>Results take time to build momentum and most people aren’t patient.</p><p><strong>3) People still don’t realize the compounding nature of readership growth.</strong></p><p>Business, online or offline, requires people and a product.</p><p>People come from ads, geographic location (for physical businesses), manual outreach like cold calls or email, or growing a readership through content creation in the new digital society.</p><p>Most businesses spend hours each day attempting to acquire customers.</p><p>They neglect the power of social media.</p><blockquote><p>My creator philosophy:\\</p><ol><li><p>Go large and broad so you can talk about whatever you want.\\</p></li><li><p>Your newsletter, products, and services create beginner to advanced niche sub-audiences.\\</p></li></ol><p>A map that guides people through the hierarchy of needs as you self-actualize.</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1667519489192128512?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 10, 2023</a></p></blockquote><p>My point being:</p><p>If a brand with 50,000 followers can make $50,000 a month (yes, this is the low end <em>if you know what you are doing</em>)…</p><p>I can make that much with one-tenth of the effort if I have 500,000 followers.</p><p>Now imagine if I have 2 million (which I do), I can make that much in an hour a week.</p><p>In other words:</p><p>I can make 10x the amount of most people because of the focus I’ve invested over the years. And I don’t care to work longer for the sake of status and fitting in with other entrepreneurs.</p><p>Me writing one tweet is the same as a beginner writing 10,000 (both in terms of high performing ideas due to practice and the spread of that tweet).</p><blockquote><p>I know an entrepreneur who works 14 hrs a day\\</p><p>And is stuck living in the basement\\</p><p>I know an entrepreneur who works 5 hrs a day\\</p><p>And has built/sold 3 companies for $100m+ each\\</p><p>The value isn&#39;t in how many hours you work\\</p><p>But where you focus your attention/awareness/consciousness</p><p>— Tej Dosa (@ComedicBizman) <a href="https://twitter.com/ComedicBizman/status/1667192394536611841?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">June 9, 2023</a></p></blockquote><p>No other traffic generation holds that power.</p><p>The harsh reality is that most people don’t stick it out long enough. They never reach the point where they can get a month’s worth of results in one day.</p><p>Most people aren’t increasing their skill level, they are increasing the amount of time they spend at their current skill level.</p><p>I teach this holistic business model in my <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics Masterclass</a> to turn yourself into a business.</p><p><strong>Now,</strong> <em><strong>why</strong></em> <strong>do I only work 4 hours a day?</strong></p><p>It seems like more and more young entrepreneurs boast about working all the time.</p><p>12-14 hour days.</p><p>There’s nothing wrong with this, and I’m sure it can be rather enjoyable. Entrepreneurship is a game. A very fun game at that.</p><p>But, there’s a glaring problem with that lifestyle.</p><p>Overwork is the antagonist of holistic development, and holism is the catalyst to exponential growth toward self-transcendence.</p><p>People wonder why I work 3-4 hours a day (on an average day, nothing is permanent)…</p><p>I wonder why they don’t if they value self-actualization.</p><p>If you are so focused on something as neutral as money, how do you have time for creativity, relationships, and health?</p><p>Think of a talent tree in a video game.</p><p><img src="'+t+'" alt=""></p><p>You won’t have access to higher levels of skill development if you only focus on one path.</p><p>You can push to a certain level in business, but to reach new heights, you have to reach an equal level of development in health, relationships, and cognitive development.</p><p>To my point above about getting 1 month of results in 1 day, this is close to impossible if you are <em>only</em> focused on business.</p><p>“Focusing on one thing” <em>requires</em> you to focus on a multitude of things to do that one thing better. It’s counterintuitive as most good things in life are.</p><h2 id="the-psychology-and-futility-of-9-5-jobs" tabindex="-1">The Psychology (And Futility) Of 9-5 Jobs <a class="header-anchor" href="#the-psychology-and-futility-of-9-5-jobs" aria-label="Permalink to &quot;The Psychology (And Futility) Of 9-5 Jobs&quot;">​</a></h2><p>Let’s open this can of worms by making a hard distinction between work and rest.</p><p>We will classify <em>work</em> as “productivity mode” and <em>rest</em> as “creativity mode.”</p><p>Both are states of mind that are determined by what, how, and why your attention is focused on what it is.</p><p><img src="'+r+'" alt=""></p><p><strong>Productivity Mode</strong></p><p>This is a narrow focused state of attention.</p><p>You are fixated on solving a problem that a task presents.</p><p>It is almost always accompanied by a sense of stress or pressure to perform.</p><p>In psychology, this is best illustrated by the <em>Task Positive Network</em> in the brain that, <em>“is active during attention-demanding tasks and includes our conscious attention towards the <strong>external</strong> environment.”</em></p><p><strong>Creativity Mode</strong></p><p>This is an open focused state of attention.</p><p>You do not fixate on a stress-related task, but you can still be focused on a task.</p><p>You are not actively paying attention.</p><p>This is why you feel so creative in the shower, at the gym, on a walk, or laying out in the sun.</p><p>In psychology, this is best illustrated by the Default Mode Network that activates when we shift from outward to <strong>inward</strong>-focused cognition.</p><p><strong>The Problem</strong></p><p>Overworkers don’t realize that habits are not only what you do, but who you are.</p><p>A state of mind, like productivity mode, can become conditioned into your mind.</p><p>You can live in that narrow and stressful perspective in a way that silently wreaks havoc on your health.</p><p>And that’s just the thing…</p><p>You don’t care.</p><p>Why?</p><p>Because that’s all you know.</p><p>You become more egotistical and selfish simply because you can’t fathom a better way of living.</p><p>Your current level of awareness/consciousness doesn’t allow you to grasp at the higher rung of the ladder because it’s clouded by fog.</p><p>Your life is so mechanical and “known” that it never crosses your mind that there is an unknown that can benefit you.</p><p>Your identity is threatened at the thought that you could see more progress while working 3-4 hours a day. And you’re fearful of the unknown lifestyle you would be thrown into.</p><p>So the ego constricts its grip on your way of living and you keep on doing what you were doing.</p><p><strong>The Evolution</strong></p><p>I’m not saying that productivity mode is bad.</p><p>In fact, it’s one of the most enjoyable states of mind to be in.</p><p>Secure, certain, and focused so that negative thoughts don’t replicate in your mind.</p><p>That’s not the problem.</p><p>The problem is never breaking out of that state to reflect on your past and re-aim toward your future.</p><p>You never <em>zoom out</em> to see where you are going so you can <em>zoom in</em> and make better choices.</p><p>Most people are zoomed in for life. They wake up one day wondering where they went wrong.</p><p>Zoom out.</p><p>Identify a big goal to gain vision.</p><p>Perceive your daily choices from the lens of that goal.</p><p>Most hard-working entrepreneurs would scoff at the fact that they are the exact same as 9-5ers, but they are.</p><p>The best way to explain this is with the <em>skill:challenge match:</em></p><p><img src="'+o+'" alt=""></p><p>Challenge the key to maximum enjoyment (flow state).</p><p>I talk about this in <a href="/letters/life-is-a-game-heres-how-you-play-it">Life Is A Video Game</a>.</p><p>Challenge narrows the mind on a problem standing in the way of a meaningful goal, which is the driver of evolution.</p><p>We can all feel “the pull” towards our highest version.</p><p>This is evolution calling you to live in accordance with nature.</p><p>What people don’t realize is this is an ever-evolving way of life.</p><p>Stagnation = death.</p><p>In order to reach new levels of challenge to focus your attention you must:</p><ul><li>Never stop learning to stack new skills and perspectives</li><li>Increase the complexity of your character to be able to even perceive the challenge</li><li>Solve deeper problems in your life so you don’t get trapped in the superficial</li></ul><p>This is my gripe with most 9-5s.</p><p>Yes, some allow you to progress, but it is a slow grind with an inevitable cap.</p><p>I see 9-5 jobs as a stepping stone.</p><p>They breed complacency and are dangerous for your psyche.</p><p>Challenge is what makes life fun and interesting.</p><p>If you halt your personal evolution by never pursuing something more, you lose purpose and fulfillment.</p><p>Now, of course, people have their own goals.</p><p>People can achieve a sustained level of happiness at a lifelong 9-5 and mindfulness methods.</p><p>But I am not speaking to those people.</p><p>I am speaking to you.</p><p>A person who clearly has a thirst for more.</p><p>An innate curiosity to discover your potential.</p><p>Or else you wouldn’t be reading this.</p><h2 id="creativity-leverage" tabindex="-1">Creativity &amp; Leverage <a class="header-anchor" href="#creativity-leverage" aria-label="Permalink to &quot;Creativity &amp; Leverage&quot;">​</a></h2><blockquote><p>If the work doesn’t require creativity, delegate it, automate it, or leave it.</p><p>— Naval (@naval) <a href="https://twitter.com/naval/status/1311199771676176384?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">September 30, 2020</a></p></blockquote><p>Creativity is the balance to productivity.</p><p>A constant need to be productive leads to a constant level of stress.</p><p>A constant level of stress leads to surface-level living. You don’t even realize there is depth to this life. You have difficulty opening your mind beyond work-related tasks.</p><p>This impacts every other area of your life.</p><ul><li>Your relationship with your friends and loved ones.</li><li>Your ability to recover from health-related activities.</li><li>Your mental capacity and development (which dictates your future level of true wealth).</li></ul><p>4-hour workdays, singular focus, and meaningful work are becoming the norm in small pockets of the internet, and for good reason.</p><p>Ancient Romans and Greeks, Steve Jobs, Charles Darwin, and an ever-growing list of visionaries, strategists, and innovators attribute their success to surprisingly low work times accompanied by an abundance of restful activities like long walks.</p><p>When we see someone with a respectable body of creative work, we would expect them to work long hours, obsessing into the night about the details of their next piece.</p><p>Instead, we see the opposite.</p><p>Like Darwin arriving at his study by eight after his morning walk and breakfast.</p><p>He would work for an hour and a half, take a break to read the mail and write letters, then return to more serious work where he conducted his experiments.</p><p>By noon Darwin would stop his work day and head out on a long walk.</p><p>After reading and answering a few more letters he would take a nap, take another walk, and return to his study for another work block.</p><p>3-5 hours of work paired with active rest seems to be the sweet spot for most impactful creatives.</p><p>Writers from multiple domains like Hemingway, Tarantino, and Ogilvy would spend the majority of their days lounging by the pool, talking to beautiful women, and doing everything aside from what they deemed work.</p><p>They gave room for the creative emergence of ideas that fueled the impact of their work.</p><p>If they can change culture and business with their methods, why can’t corporate workaholics do the same?</p><p>If you’re wondering “how,” to do this, I’ve written about it extensively before.</p><p>Here are my <a href="/letters/the-4-hour-workday-focused-work-changed-my-life">10 commandments of the 4-hour workday</a> and <a href="/letters/change-your-life-in-6-months-my-deep-work-routine">my deep work routine</a>.</p><h2 id="the-new-currency" tabindex="-1">The New Currency <a class="header-anchor" href="#the-new-currency" aria-label="Permalink to &quot;The New Currency&quot;">​</a></h2><p>How do you make money?</p><p>First, you need attention.</p><p>Second, you need a product or service to direct that attention to.</p><p>Third, you need to understand the process of <em>guiding attention</em> throughout that journey.</p><p>Some people may reach your product and buy randomly.</p><p>In most cases, that is not sustainable.</p><p>You must create and understand every single touchpoint that a user can come in contact with on your brand.</p><p>Some call this a “funnel,” but that has negative connotations associated with shady marketers.</p><p>My funnel is simple:</p><ul><li>Write a big-idea-centric newsletter every week.</li><li>Write 3 punchy and memorable tweets every day.</li><li>Repurpose them to all platforms (my newsletter is my YouTube script, <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">I teach you how I write them here</a>).</li></ul><p><img src="'+a+'" alt=""></p><p>You must capture, hold, and nurture their attention with <em>ideas.</em></p><p><em>Ideas are the new currency.</em></p><p><em>Modern success is mental warfare.</em></p><p><em>Creativity, rest, and short work hours are the catalyst.</em></p><p>This is something I realized late in my journey.</p><p>Here’s what you need to focus on:</p><p><strong>If you don’t</strong> <strong>prioritize</strong> <strong>depth, you will not</strong> <strong>be remembered</strong>**.**</p><p>Your authority is determined by how much attention you hold throughout your lifetime.</p><p>A tweet may hold 10 seconds of attention.</p><p>A book holds 5-6 hours of attention.</p><p>You become what you consume, and you mold those who read your work.</p><p>Books, newsletters, podcasts, and YouTube videos.</p><p>These are the foundation of your brand.</p><p>This is how you nurture an audience without needing pushy sales tactics and direct response marketing.</p><p>When you prioritize depth, understanding, and novel perspectives you build trust and equity with your audience that you can cash in when it’s time to promote.</p><p>Who do you remember?</p><p>The person on Twitter with a tweet you liked?</p><p>Or the author that changed how you move in the world?</p><p>I don’t remember everything I read from Eckhart Tolle, but I will spread his work to anyone curious about who impacted my life the most.</p><p>He makes money off of me because he lives rent-free in my head.</p><h3 id="the-fill-empty-use-framework-for-a-holistic-lifestyle" tabindex="-1">The Fill-Empty-Use Framework For A Holistic Lifestyle <a class="header-anchor" href="#the-fill-empty-use-framework-for-a-holistic-lifestyle" aria-label="Permalink to &quot;The Fill-Empty-Use Framework For A Holistic Lifestyle&quot;">​</a></h3><blockquote><p>Fill your brain in the afternoons with books, learning, and socialization\\</p><p>Empty your brain before bed with journaling, planning, and meditation\\</p><p>Use your brain in the morning with creation, output, and focus</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1456553636700504065?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 5, 2021</a></p></blockquote><p>In the afternoons, fill your mind through:</p><p><strong>Curiosity pursuit</strong> to collect kernels of truth to integrate into your worldview.</p><p><strong>Skill acquisition</strong> to increase your value in the marketplace that continues to change. If you stop learning, you die.</p><p><strong>Intellectual conversation</strong> so you don’t get trapped in a narrow perspective. You need to test your ideas with an open mind. Avoid debate and argument.</p><p>All of which can be used as fuel for your creative work.</p><p>In the afternoons, empty your mind through:</p><p><strong>Self-reflection</strong> to note mistakes, lessons, and directions that you would have missed otherwise.</p><p><strong>Reality mapping</strong> (or documenting what you learned for the day and how it connects to other ideas) so you can create something of value.</p><p><strong>Spiritual connection</strong> so you don’t get trapped in “doing” mode. Embrace “being” to balance out the stress.</p><p>In the morning, use your mind through:</p><p><strong>Focused work</strong> to channel your discoveries and practice your craft.</p><p><strong>Priority projects</strong> to have direction for your work. This is the only way to produce something that you can pass off to other people (and get paid for doing so).</p><p>More on priority projects here: <a href="/letters/change-your-life-in-6-months-my-deep-work-routine">Change Your Life In 6 Months (My Deep Work Routine</a>).</p><p><strong>Bursts of intensity</strong> so you feel a sense of accomplishment first thing in the morning. You can be at ease during your rest knowing that you knocked out what needs to be done.</p><p>Ending it here.</p><p>Enjoy the rest of your week.</p><p>– Dan Koe</p>',200)])])}const b=n(h,[["render",l]]);export{k as __pageData,b as default};
